style:
@import url('https://googleapis.com');

/* =========================================
   MEMENTO MIDDLE HEADER (ABOVE BLOCK)
   ========================================= */
.memento-page-header {
    text-align: center;
    width: 100%;
    margin-bottom: 24px;
}

.memento-page-header h1 {
    margin: 0;
    font-size: 44px; /* Slightly increased for script font clarity */
    font-weight: 900; /* Script fonts usually display best at a normal weight */
    letter-spacing: normal; /* Restored script tracking for natural link cursive strokes */
    color: #31183b;
    font-family: 'Petit Formal Script', cursive, sans-serif;
}

/* =========================================
   MEMENTO HERO CORE CONTAINER
   ========================================= */
.memento-hero {
    position: relative;
    width: 100%;
    min-height: 185px; 
    overflow: hidden;
    border-radius: 12px;
    background: linear-gradient(105deg, #f4eef5 0%, #f6eaf0 35%, #faf1f3 65%, #fff4ee 100%);
    color: #442a47; 
    padding: 30px 32px;
    box-sizing: border-box;
    display: flex;
    justify-content: space-between;
    align-items: flex-start;
}

/* =========================================
   LEFT SIDE TEXT CONTENT
   ========================================= */
.memento-hero-content {
    position: relative;
    z-index: 5;
    flex: 1;
    max-width: 60%;
}

.memento-brand {
    display: flex;
    align-items: center;
    gap: 14px;
}

.memento-logo {
    width: 42px;
    height: 42px;
    display: flex;
    align-items: center;
    justify-content: center;
    border-radius: 10px;
    background: rgba(68, 42, 71, 0.08);
    backdrop-filter: blur(8px);
    border: 1px solid rgba(68, 42, 71, 0.15);
    color: #442a47;
}

.memento-subtitle {
    margin: 0;
    font-size: 14px;
    font-weight: 500;
    color: #633b52;
}

.memento-welcome {
    margin-top: 20px;
}

.memento-welcome h2 {
    margin: 0 0 6px;
    font-size: 16px;
    font-weight: 600;
    color: #442a47;
}

.memento-welcome p {
    margin: 0;
    font-size: 12.5px;
    line-height: 1.5;
    color: #633b52;
    max-width: 480px;
}

/* =========================================
   PREMIUM HIGH-PERFORMANCE LINK BUTTON 
   ========================================= */
.memento-btn-track {
    position: relative;
    display: inline-flex;
    margin-top:10px;
    align-items: center;
    gap: 15px;
    background: #442a47;
    color: #ffffff !important;
    text-decoration: none !important;
    padding: 10px 25px;
    font-size: 13px;
    font-weight: 600;
    border-radius: 8px;
    overflow: hidden;
    box-shadow: 0 4px 14px rgba(68, 42, 71, 0.15);
    transition: transform 0.2s cubic-bezier(0.25, 1, 0.5, 1), 
                box-shadow 0.2s cubic-bezier(0.25, 1, 0.5, 1);
}

/* Shimmer overlay effect line */
.memento-btn-track::before {
    content: '';
    position: absolute;
    top: 0;
    left: -100%;
    width: 100%;
    height: 100%;
    background: linear-gradient(
        90deg,
        transparent,
        rgba(255, 255, 255, 0.15),
        transparent
    );
    transition: none;
}

.memento-btn-icon {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    transition: transform 0.3s cubic-bezier(0.34, 1.56, 0.64, 1);
}

/* --- Animation Hover States --- */
.memento-btn-track:hover {
    transform: translateY(-2px);
    box-shadow: 0 6px 20px rgba(68, 42, 71, 0.28);
}

/* Trigger shifting line animation loop on hover */
.memento-btn-track:hover::before {
    left: 100%;
    transition: left 0.65s cubic-bezier(0.25, 1, 0.5, 1);
}

/* Smooth forward spring pop for the icon */
.memento-btn-track:hover .memento-btn-icon {
    transform: translateX(4px) scale(1.1);
}

/* Tactile push mechanism on click */
.memento-btn-track:active {
    transform: translateY(1px);
    box-shadow: 0 2px 8px rgba(68, 42, 71, 0.2);
}

/* =========================================
   RIGHT SIDE GRAPHICS LAYERING
   ========================================= */
.memento-graphics-wrapper {
    position: absolute;
    top: 0;
    right: 0;
    bottom: 0;
    width: 50%;
    z-index: 2;
    overflow: hidden;
}

.memento-sun {
    position: absolute;
    width: 56px;
    height: 56px;
    right: 70px;
    bottom: 45px;
    border-radius: 50%;
    background: #ffeba2;
    z-index: 1;
    box-shadow: 0 0 35px rgba(255, 235, 162, 0.5);
}

.memento-mountains {
    position: absolute;
    bottom: -2px;
    right: 0;
    width: 100%;
    height: 100%;
    z-index: 2;
    pointer-events: none;
}

.memento-quote {
    position: absolute;
    z-index: 4;
    right: 170px;
    top: 25px;
    text-align: center;
    font-family: 'Georgia', serif;
    font-size: 14px;
    font-style: italic;
    color: #633b52; 
    line-height: 1.3;
    pointer-events: none;
}

.memento-quote span {
    display: block;
}

.quote-text-top {
    font-weight: 400;
}

.quote-text-bottom {
    font-size: 15px;
    font-weight: 600;
    padding-left: 10px;
}

script:
(() => {
    const root = root_element;
    const list = root.querySelector("#memento-todo-list");

    if (!list) {
        console.error("Could not find #memento-todo-list");
        return;
    }

    list.textContent = "Loading tasks...";

    frappe.call({
        method: "memento.api.get_workspace_todos",

        callback: function (response) {
            console.log("API response:", response);

            const result = response.message;

            if (!result || !result.success) {
                list.textContent = "Unable to load tasks.";
                return;
            }

            const items = result.items || [];

            list.replaceChildren();

            if (items.length === 0) {
                list.textContent = "No tasks found.";
                return;
            }

            items.forEach(function (row) {
                const item = document.createElement("div");
                item.className = "memento-todo-item";
                item.style.cursor = "pointer";

                // ToDo title and date
                const content = document.createElement("div");
                content.className = "memento-todo-item-content";

                const title = document.createElement("div");
                title.className = "memento-todo-item-title";
                title.textContent = row.task || "Untitled task";

                const date = document.createElement("div");
                date.className = "memento-todo-item-date";

                if (row.time) {
                    const parsedDate = new Date(
                        row.time.replace(" ", "T")
                    );

                    date.textContent = isNaN(parsedDate.getTime())
                        ? row.time
                        : parsedDate.toLocaleString();
                }

                content.appendChild(title);
                content.appendChild(date);

                // Right section
                const right = document.createElement("div");
                right.className = "memento-todo-item-right";

                // Status badge
                const status = document.createElement("span");
                status.className = "memento-todo-status";

                const statusValue = row.status || "Pending";
                status.textContent = statusValue;

                const normalizedStatus = statusValue.toLowerCase();

                if (
                    ["completed", "complete", "done"].includes(normalizedStatus)
                ) {
                    status.classList.add("memento-status-completed");
                } else if (
                    ["in progress", "working"].includes(normalizedStatus)
                ) {
                    status.classList.add("memento-status-progress");
                } else {
                    status.classList.add("memento-status-open");
                }

                // Arrow link
                const arrow = document.createElement("a");
                arrow.className = "memento-todo-arrow";
                arrow.textContent = "›";
                arrow.title = "Open ToDo";
                arrow.href = "/todo?" + new URLSearchParams({
                    todo: row.name || "",
                    task: row.parent || "",
                    project: row.project || ""
                }).toString();

                // Make the entire row clickable
                item.addEventListener("click", function (event) {
                    if (event.target.closest("a")) {
                        return;
                    }

                    window.location.href = arrow.href;
                });

                right.appendChild(status);
                right.appendChild(arrow);

                item.appendChild(content);
                item.appendChild(right);

                list.appendChild(item);
            });

            console.log("Displayed tasks:", items.length);
        },

        error: function (error) {
            console.error("API request failed:", error);
            list.textContent = "Failed to load tasks. Check console.";
        }
    });
})();

style:
.memento-todo-widget {
    width: 100%;
    height: 270px;
    padding: 18px 6px 0;
    box-sizing: border-box;
    font-family: inherit;
    background: #ffffff;

    /* Overflow effect */
    overflow-y: auto;
    overflow-x: hidden;
    scroll-behavior: smooth;
}

/* Custom scrollbar */
.memento-todo-widget::-webkit-scrollbar {
    width: 6px;
}

.memento-todo-widget::-webkit-scrollbar-track {
    background: #f5f0f5;
    border-radius: 10px;
}

.memento-todo-widget::-webkit-scrollbar-thumb {
    background: #c7b5cc;
    border-radius: 10px;
}

.memento-todo-widget::-webkit-scrollbar-thumb:hover {
    background: #8e7298;
}

.memento-todo-heading {
    font-size: 15px;
    font-weight: 500;
    color: #333333;
    margin-bottom: 18px;
}

#memento-todo-list {
    display: flex;
    flex-direction: column;
    gap: 18px;
}

.memento-todo-item {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 15px;
    width: 100%;
}

.memento-todo-item-content {
    flex: 1;
    min-width: 0;
}

.memento-todo-item-title {
    font-size: 14px;
    font-weight: 400;
    color: #444444;
    overflow-wrap: anywhere;
    margin-bottom: 4px;
}

.memento-todo-item-date {
    font-size: 11px;
    color: #888888;
}

.memento-todo-item-right {
    display: flex;
    align-items: center;
    gap: 10px;
    flex-shrink: 0;
}

.memento-todo-status {
    display: inline-flex;
    align-items: center;
    gap: 5px;
    padding: 3px 10px;
    border-radius: 20px;
    font-size: 12px;
    white-space: nowrap;
}

.memento-todo-status::before {
    content: "";
    width: 6px;
    height: 6px;
    background: currentColor;
    border-radius: 50%;
}

.memento-status-open {
    color: #d12d32;
    background: #fff0f0;
}

.memento-status-completed {
    color: #168653;
    background: #eaf8f0;
}

.memento-status-progress {
    color: #a66b00;
    background: #fff5df;
}

.memento-todo-arrow {
    font-size: 19px;
    color: #777777;
    text-decoration: none;
    line-height: 1;
}

.memento-todo-arrow:hover {
    color: #333333;
}

.memento-todo-empty {
    padding: 18px 0;
    color: #888888;
    font-size: 13px;
}

.memento-todo-view-list {
    display: block;
    width: 100%;
    height: 27px;
    margin-top: 24px;
    padding: 3px 10px;
    border: none;
    border-radius: 9px;
    background: #f1f1f1;
    color: #555555;
    font-size: 14px;
    cursor: pointer;
    transition: background 0.2s ease;
}

.memento-todo-view-list:hover {
    background: #e5e5e5;
}
